        List<FormElement> forms = doc.forms();
        Assert.assertNotNull(forms);
        Assert.assertTrue(forms.isEmpty());
    }

    @Test
    public void titleTest() {
        Document doc = new Document("http://www.google.com");
        doc.title("Google");
        Assert.assertEquals("Google", doc.title());
    }

